                                                            opacity: 0;
                                                            transition: opacity 0.15s;
                                                            position: absolute;
                                                            top: 50%;
                                                            left: 50%;
                                                            transform: translate(-50%, -50%);
                                                        }

                                                        .custom-radio-label input[type="checkbox"]:checked+.custom-radio-circle {
                                                            border-color: #FFD88C;
                                                            background: #FFF;
